 * Utilities for extracting and summarizing agent trajectories from trace data.
 *
 * A trajectory is the ordered sequence of execution steps an agent took while
 * working toward a goal — tool calls, command executions, searches, reasoning
 * steps, etc. These utilities normalize raw trace spans into a consistent
 * shape that can be asserted against or summarized for an LLM judge.
 */

import type { TraceData, TraceSpan } from '../types/tracing';

export type TrajectoryStepType = 'tool' | 'command' | 'reasoning' | 'search' | 'span';

export interface TrajectoryStep {
  /** Normalized classification of the step. */
  type: TrajectoryStepType;
  /** The primary, human-meaningful name of the step. */
  name: string;
  /** The original span name (may differ from `name`). */
  spanName: string;
  /** Alternative names this step can be referred to by (e.g. command basename). */
  aliases: string[];
}

/** Matches spans that represent a reasoning step. */
const REASONING_PATTERN = /^reasoning/i;

/**
 * Determines whether a span with a `query` attribute looks like a search
 * (as opposed to, e.g., a SQL query span which also carries a query but is
 * not a search).
 */
function isSearchLikeSpanName(spanName: string): boolean {
  return /search|retriev|semantic|vector|lookup/i.test(spanName);
}

/**
 * Extract the first word of a command string, e.g. `ls` from `ls -la`.
 */
function firstWord(command: string): string {
  const trimmed = command.trim();
  if (!trimmed) {
    return command;
  }
  return trimmed.split(/\s+/)[0];
}

/**
 * Classify a single trace span into a normalized trajectory step.
 */
function classifySpan(span: TraceSpan): TrajectoryStep {
  const attributes = span.attributes || {};
  const spanName = span.name;

  // Generic tool call span (OTEL-style `tool.name` attribute).
  const toolName = attributes['tool.name'];
  if (typeof toolName === 'string' && toolName.length > 0) {
    return {
      type: 'tool',
      name: toolName,
      spanName,
      aliases: [],
    };
  }

  const itemType = attributes['codex.item.type'];

  // MCP tool call span. Name is the clean tool name; the original span name
  // (e.g. `mcp inventory/search_inventory`) is preserved as an alias.
  if (itemType === 'mcp_tool_call') {
    const mcpTool = attributes['codex.mcp.tool'];
    if (typeof mcpTool === 'string' && mcpTool.length > 0) {
      return {
        type: 'tool',
        name: mcpTool,
        spanName,
        aliases: [spanName],
      };
    }
  }

  // Command execution span. Name is the full command; the first word (e.g.
  // `ls`) is preserved as an alias.
  if (itemType === 'command_execution') {
    const command = attributes['codex.command'];
    if (typeof command === 'string' && command.length > 0) {
      return {
        type: 'command',
        name: command,
        spanName,
        aliases: [firstWord(command)],
      };
    }
  }

  // Reasoning span (matched by name pattern).
  if (REASONING_PATTERN.test(spanName)) {
    return {
      type: 'reasoning',
      name: spanName,
      spanName,
      aliases: [],
    };
  }

  // Search span. A `query` attribute on a search-like span becomes a search;
  // a `query` attribute on a non-search span (e.g. SQL) falls back to `span`.
  const query = attributes['query'] ?? attributes['codex.search.query'];
  if (typeof query === 'string' && query.length > 0 && isSearchLikeSpanName(spanName)) {
    return {
      type: 'search',
      name: query,
      spanName,
      aliases: [],
    };
  }

  // Fallback: an uncategorized span.
  return {
    type: 'span',
    name: spanName,
    spanName,
    aliases: [],
  };
}

/**
 * Accepts a TraceData object and returns an array of normalized trajectory
 * steps, one per span, in span order.
 */
export function extractTrajectorySteps(trace: TraceData): TrajectoryStep[] {
  const spans = trace?.spans;
  if (!Array.isArray(spans)) {
    return [];
  }
  return spans.map((span) => classifySpan(span));
