function compactSteps(steps: TrajectoryStep[]): SummaryStepEntry[] {
  const entries: SummaryStepEntry[] = [];
  let i = 0;
  while (i < steps.length) {
    const step = steps[i];
    let count = 1;
    let j = i + 1;
    while (j < steps.length && steps[j].type === step.type && steps[j].name === step.name) {
