    outputSteps = [...head, { omittedCount }, ...tail];
  } else {
    outputSteps = compacted;
  }

  return JSON.stringify(
    {
      stepCount: steps.length,
      compactedStepCount,
      steps: outputSteps,
    },
    null,
    2,
  );
}
